# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GAZİ MUSTAFA KEMAL VE SIĞIRTMAÇ MUSTAFA: HİKÂYE UNSURLARI</text>\n  <rect x="20" y="46" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Şahıs Kadrosu, Mekân ve Zaman</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Şahıs ve Varlık Kadrosu:</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" fill="#334155">Gazi Mustafa Kemal Atatürk, küçük çoban</text>\n  <text x="180" y="128" text-anchor="middle" font-size="11" fill="#334155">Sığırtmaç Mustafa, yaver/arkadaşları, doktorlar.</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Mekân (Yer):</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11" fill="#334155">Yalova civarındaki kır yolu, çiftlik ve hastane.</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Zaman:</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">Cumhuriyet\'in ilk yılları (1929 yılı sonbaharı).</text>\n\n  <rect x="360" y="46" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Metnin Bölümleri (Serim - Düğüm - Çözüm)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Serim (Giriş): Atatürk\'ün Yalova\'da gezintiye</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#334155">çıkması, yolu şaşırınca Sığırtmaç Mustafa\'ya rastlaması.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Düğüm (Gelişme): Küçük Mustafa\'nın dürüstlüğü,</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">tokgözlülüğü (parayı almaması) ve Atatürk\'le sohbeti.</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Çözüm (Sonuç): Atatürk\'ün hasta olan Mustafa\'yı</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" fill="#334155">tedavi ettirip okula yazdırması ve subay yetiştirmesi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZCÜKTE YAPI: KÖK, YAPIM EKİ VE ÇEKİM EKİ</text>\n  <rect x="20" y="46" width="320" height="192" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Yapım Ekleri (Anlam Değiştiren Ekler)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e293b">Eklendiği kökün anlamını (ve bazen türünü)</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">değiştirerek TÜREMİŞ SÖZCÜK oluşturur:</text>\n  <text x="180" y="138" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• sığırtmaç + lık ➔ sığırtmaçlık</text>\n  <text x="180" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• göz + lük + çü ➔ gözlükçü</text>\n  <text x="180" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• sev- + gi + li ➔ sevgili</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" fill="#334155">Başlıca ekler: -lık, -lı, -sız, -cı, -gi, -gin, -daş</text>\n\n  <rect x="360" y="46" width="320" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Çekim Ekleri (Görev Belirten Ekler)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#1e293b">Sözcüğün anlamını değiştirmez; cümle içinde</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">diğer sözcüklerle bağ kurmasını sağlar:</text>\n  <text x="520" y="138" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• Çoğul eki: çocuk-lar, ağaç-lar</text>\n  <text x="520" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• Hal (durum) ekleri: yol-u, çiftlik-te, köy-den</text>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• İyelik (aitlik) ekleri: ceviz-im, baba-sı</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" fill="#334155">Türkçede önce yapım eki, sonra çekim eki gelir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZ SANATLARI, BAĞLANTI İFADELERİ VE NOKTALAMA</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Söz Sanatları ve Bağlamdan Anlam</text>\n  <text x="182" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Benzetme (Teşbih): Zayıf olanın güçlüye</text>\n  <text x="182" y="116" text-anchor="middle" font-size="11" fill="#334155">\'gibi, kadar\' ile benzetilmesi (altın gibi sarı saçlar).</text>\n  <text x="182" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Kişileştirme (Teşhis): İnsan özelliğinin doğaya</text>\n  <text x="182" y="160" text-anchor="middle" font-size="11" fill="#334155">aktarılması (hüzünlü bulutlar, gülümseyen güneş).</text>\n  <text x="182" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Karşıtlık (Tezat): Zıt kavramların bir arada</text>\n  <text x="182" y="204" text-anchor="middle" font-size="11" fill="#334155">kullanılması (varlık-yokluk, hastalık-sağlık).</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Bağlantı İfadeleri ve Noktalama</text>\n  <text x="517" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Düşünceyi Değiştirenler:</text>\n  <text x="517" y="116" text-anchor="middle" font-size="11" fill="#334155">ama, fakat, lakin, ancak, oysa, buna rağmen</text>\n  <text x="517" y="140" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Neden-Sonuç ve Özetleyenler:</text>\n  <text x="517" y="158" text-anchor="middle" font-size="11" fill="#334155">çünkü, bu nedenle, böylece, kısacası, özetle</text>\n  <text x="517" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Konuşma Çizgisi (—) ve İki Nokta (:):</text>\n  <text x="517" y="204" text-anchor="middle" font-size="11" fill="#334155">Diyaloglarda sözden önce (:), satır başında (—)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
